INSERT INTO `blogs` (`id`, `heading`, `slug`, `cate_id`, `content`, `image`, `featured`, `meta_title`, `lang`, `meta_keywords`, `meta_descriptions`, `remember_token`, `created_at`, `updated_at`) VALUES
(1, 'Başarılı İş Görüşmesi İçin 5 İpucu', 'basarili-is-gorusmesi-icin-5-ipucu', '', 'İş görüşmesine giderken neler yapmalısınız? Bu yazıda, başarılı bir iş görüşmesi için gerekli olan 5 önemli ipucunu sizlerle paylaşıyoruz. Doğru hazırlık yaparak, özgüveninizi artırarak ve iyi bir izlenim bırakarak, hayalinizdeki işi elde etme şansınızı artırabilirsiniz.', 'blog-1_450_498.jpg', '0', NULL, 'tr', NULL, NULL, NULL, '2025-12-19 05:23:01', '2025-12-19 05:23:01'),
(2, 'Özgeçmiş Yazarken Dikkat Edilmesi Gereken Noktalar', 'ozgecmis-yazarken-dikkat-edilmesi-gereken-noktalar', '', 'Özgeçmiş, işveren ile ilk iletişim noktanızıdır. Profesyonel bir özgeçmiş yazarak, işverenin dikkatini çekebilir ve iş görüşmesine davet edilme şansınızı artırabilirsiniz. Bu yazıda, özgeçmiş yazarken dikkat edilmesi gereken önemli noktaları inceleyeceğiz.', 'blog-2_189.jpg', '0', NULL, 'tr', NULL, NULL, NULL, '2025-12-19 05:23:01', '2025-12-19 05:23:01'),
(3, 'Kariyer Gelişimi İçin Gerekli Beceriler', 'kariyer-gelisimi-icin-gerekli-beceriler', '', 'Günümüzün rekabetçi iş piyasasında, teknik beceriler kadar soft skills de önemlidir. İletişim, liderlik, problem çözme ve takım çalışması gibi beceriler, kariyer gelişiminizde önemli rol oynar. Bu yazıda, kariyer gelişimi için gerekli olan temel becerileri inceleyeceğiz.', 'blog-3_532.jpg', '0', NULL, 'tr', NULL, NULL, NULL, '2025-12-19 05:23:01', '2025-12-19 05:23:01');
