INSERT INTO `seo` (`id`, `page_title`, `slug`, `route_name`, `controller_action`, `is_static`, `seo_title`, `seo_description`, `seo_keywords`, `seo_other`, `created_at`, `updated_at`) VALUES
(1, 'front_index_page', NULL, 'index', NULL, 0, 'Personel Noktası - En Güncel İş İlanları ve Kariyer Fırsatları', 'Personel Noktası ile hayalinizdeki işe ulaşın. Binlerce güncel iş ilanı, kariyer tavsiyeleri ve seçkin şirketler sizi bekliyor.', 'personel noktası, kariyer fırsatları, iş ilanları, eleman arayan firmalar, iş bulma platformu, insan kaynakları, kariyer sitesi', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />\r\n<meta name=\"author\" content=\"Kodend\" />', '2018-08-25 20:01:47', '2026-02-12 19:44:07'),
(2, 'email_to_friend', NULL, 'email.to.friend', NULL, 0, 'İş İlanını Arkadaşına Öner | Personel Noktası', 'Beğendiğiniz iş ilanını arkadaşlarınıza e-posta ile gönderin. Personel Noktası ile kariyer fırsatlarını paylaşın.', 'iş ilanı paylaş, arkadaşa öner, iş ilanı gönder, kariyer paylaşımı, personel noktası', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />', '2018-08-25 20:03:08', NULL),
(3, 'report_abuse', NULL, 'report.abuse', NULL, 0, 'İlan Şikayeti Bildir | Personel Noktası', 'Uygunsuz veya hatalı bir iş ilanını Personel Noktası ekibine bildirin. Güvenli ve adil iş arama deneyimi için şikayetlerinizi değerlendiriyoruz.', 'şikayet bildir, ilan şikayeti, uygunsuz ilan, hatalı ilan, personel noktası iletişim', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />', '2018-08-25 20:03:26', NULL),
(4, 'faq', NULL, 'faq', NULL, 0, 'Sıkça Sorulan Sorular (SSS) | Personel Noktası', 'Personel Noktası hakkında merak ettikleriniz, üyelik, ilan verme, başvuru süreçleri ve daha fazlası için sıkça sorulan sorular ve cevapları.', 'sss, sıkça sorulan sorular, yardım, destek, personel noktası yardım, iş ilanı nasıl verilir, başvuru nasıl yapılır', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />', '2018-08-25 20:03:41', NULL),
(5, 'contact-us', 'iletisim', 'contact.us', NULL, 0, 'Bize Ulaşın - İletişim | Personel Noktası', 'Personel Noktası ile iletişime geçin. Soru, öneri ve talepleriniz için bize ulaşabilirsiniz. Destek ekibimiz size yardımcı olmaktan mutluluk duyar.', 'iletişim, bize ulaşın, personel noktası iletişim, destek, müşteri hizmetleri, iş ilanı yardım', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />', '2018-08-25 20:03:50', '2026-02-12 19:24:57'),
(6, 'search-jobs', 'is-ilanlari', 'search.jobs', NULL, 0, 'İş Ara - Binlerce Güncel İş İlanı | Personel Noktası', 'Şehir, sektör, pozisyon ve maaş kriterlerine göre iş ilanlarını filtreleyin. Personel Noktası ile aradığınız işi kolayca bulun.', 'iş ara, iş ilanı ara, güncel iş ilanları, şehre göre iş, sektöre göre iş, pozisyon ara, iş bul', '<meta name=\"robots\" content=\"ALL, FOLLOW,INDEX\" />', '2018-08-25 20:03:50', '2026-02-12 04:14:34'),
(7, 'companies', 'sirketler', 'company.listing', NULL, 0, 'Şirketler - En İyi İşverenleri Keşfedin | Personel Noktası', 'Türkiye\'nin önde gelen şirketlerini ve açık pozisyonlarını inceleyin. Hayalinizdeki şirkette kariyer fırsatlarını keşfedin.', 'şirketler, işverenler, firma listesi, en iyi işverenler, şirket profilleri, açık pozisyonlar, kariyer fırsatları', 'iş', '2026-02-12 04:00:44', '2026-02-12 04:10:05'),
(8, 'jobs', '', 'job.list', NULL, 0, 'İş İlanları - Aradığınız İşi Hemen Bulun | Personel Noktası', 'Sektörlere, pozisyonlara ve şehirlere göre en güncel iş ilanlarını inceleyin. Tam zamanlı, yarı zamanlı ve uzaktan çalışma fırsatları.', 'iş ilanları, güncel ilanlar, açık pozisyonlar, tam zamanlı iş, yarı zamanlı iş, uzaktan çalışma, kariyer, istihdam', '', '2026-02-12 15:27:48', NULL),
(10, 'evine-hizmet-al', 'evine-hizmet-al', 'home-services.all', '', 0, 'Evine Hizmet Al - Güvenilir Ev Hizmetleri | Personel Noktası', 'Temizlik, tadilat, boyacı, tesisatçı ve daha fazlası! Eviniz için ihtiyaç duyduğunuz tüm hizmetleri Personel Noktası üzerinden güvenle bulun.', 'evine hizmet al, ev hizmetleri, temizlik hizmeti, tadilat, boyacı, tesisatçı, ev temizliği, ev bakım hizmetleri, güvenilir hizmet', '', '2026-02-12 19:45:06', '2026-02-12 19:45:06'),
(11, 'bakici-bul', 'bakici-bul', 'caregiver.all', '', 0, 'Bakıcı Bul - Güvenilir Bakıcı Hizmetleri | Personel Noktası', 'Çocuk bakıcısı, yaşlı bakıcısı, hasta bakıcısı ve daha fazlası. Güvenilir ve deneyimli bakıcıları Personel Noktası ile kolayca bulun.', 'bakıcı bul, çocuk bakıcısı, yaşlı bakıcısı, hasta bakıcısı, bebek bakıcısı, güvenilir bakıcı, bakıcı ilanları, evde bakım', '', '2026-02-12 19:45:06', '2026-02-12 19:45:06');
