INSERT INTO `testimonials` (`id`, `testimonial_id`, `testimonial_by`, `testimonial`, `company`, `is_default`, `is_active`, `sort_order`, `lang`, `created_at`, `updated_at`) VALUES
(1, 0, 'Ahmet Yılmaz', 'Bu platform sayesinde harika bir iş buldum. Profesyonel arayüzü ve kolay kullanımı çok beğendim. Tüm iş arayanları bu platformu kullanmaya tavsiye ederim.', 'ABC Şirketi', 0, 1, 99999, 'tr', '2025-12-19 05:22:04', '2025-12-19 05:22:04'),
(2, 0, 'Fatma Kaya', 'İşveren olarak bu platform bana çok yardımcı oldu. Nitelikli adayları hızlı bir şekilde buldum ve ekibimi genişlettim. Hizmet kalitesi ve müşteri desteği harika.', 'XYZ Şirketi', 0, 1, 99999, 'tr', '2025-12-19 05:22:04', '2025-12-19 05:22:04'),
(3, 0, 'Mehmet Demir', 'Kariyer yolculuğumda bu platform bana çok katkı sağladı. Birçok fırsat buldum ve sonunda hayalımın işine ulaştım. Herkesin bu platformu denemesini öneriyorum.', 'DEF Şirketi', 0, 1, 99999, 'tr', '2025-12-19 05:22:04', '2025-12-19 05:22:04');
